# ============================================================
# Main
# ============================================================
main() {
  header "TESSERA — Fabric CA Identity Registration"
  checkBinaries
  checkDocker

  enrollOrdererOrg
  enrollIssuerOrg
  enrollVerifierOrg
  enrollComplianceOrg

  echo ""
  success "All TESSERA identities registered and enrolled successfully."
  info "Generated artifacts:"
  info "  ${ORG_DIR}/ordererOrganizations/"
  info "  ${ORG_DIR}/peerOrganizations/"
}

main "$@"
